import { Grid } from "march/ui"

// renk duvarı: 7 renk 4 sütunda; balance satırları dengeler (4 + 3), fill="stretch" son satırı doldurur
const colors = ["brand-orange", "brand-blue", "brand-green", "brand-purple", "brand-pink", "brand-gold", "danger"]

const Swatch = (props: { color: string }) => <div sx={{ p: 4, radius: 2, flex: "center", text: ["sm", "bold"] }} m:color={props.color}
  class="m-tone-solid">{props.color}</div>

export function ColorWall() {
  return <Grid cols={4} gap={2} fill="stretch" balance>
    {colors.map((c) => <Swatch color={c} />)}
  </Grid>
}

import { Grid, Card, Button, Segmented } from "march/ui"

// ürün listesi: sütun sayısı seçilir, en dar sütun 12rem (dar kutuda kendiliğinden azalır), satırlar eşit boyda
const products = [
  { name: "Kulaklık", price: 1290, note: "Gürültü engelleme" },
  { name: "Saat", price: 3490, note: "GPS ve nabız" },
  { name: "Hoparlör", price: 990, note: "Suya dayanıklı" },
  { name: "Klavye", price: 1590, note: "Mekanik, sessiz anahtarlar; arka ışıklı" },
  { name: "Fare", price: 590, note: "Kablosuz" },
]

export function ProductList() {
  let $cols = 3
  let $cart = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Segmented label="Sütun" value={String($cols)} options={["2", "3", "4"]} onChange={(v: string) => $cols = Number(v)} />
    {() => <Grid cols={$cols} minCol="12rem" equal gap={3}>
      {products.map((p) => <Card title={p.name} footer={<Button size="sm" on:click={() => $cart++}>{p.price} ₺ · Sepete ekle</Button>}>{p.note}</Card>)}
    </Grid>}
    <span sx={{ text: "sm", color: "muted" }}>Sepette {$cart} ürün</span>
  </div>
}

import { Grid } from "march/ui"

// Grid'in bütün özellikleri: cols, gap, min (otomatik sütun), fill (stretch / last), balance, minCol, equal, class
const Tile = (props: { n: number; tall?: boolean }) => <div class="sc-tile" sx={{ p: props.tall ? 6 : 2 }}><span>Kart {props.n}</span></div>
const tiles = (n: number, tall = -1) => Array.from({ length: n }, (_, i) => <Tile n={i + 1} tall={i === tall} />)

export function GridLab() {
  return <div sx={{ flex: "col", gap: 4 }}>
    <Grid class="lab-cols" cols={3} gap={2}>{tiles(5)}</Grid>
    <Grid class="lab-last" cols={3} gap={2} fill="last">{tiles(5)}</Grid>
    <Grid class="lab-balance" cols={4} gap={2} balance>{tiles(5)}</Grid>
    <Grid class="lab-min" min="10rem" gap={1}>{tiles(4)}</Grid>
    <Grid class="lab-equal" cols={2} gap={2} minCol="8rem" equal fill="stretch">{tiles(3, 0)}</Grid>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { GridLab } from "./GridLab.tsx"

// GridLab'in testleri: kaydedince Testler sekmesinde çalışır
test("her ızgara bütün kartlarını çizer", () => {
  const s = renderTest(() => <GridLab />)
  expect(s.all(".lab-cols .sc-tile").length).toBe(5)
  expect(s.all(".lab-min .sc-tile").length).toBe(4)
})

test("fill son satırın sınıfını verir", () => {
  const s = renderTest(() => <GridLab />)
  expect(s.get(".lab-last")?.className).toContain("m-grid-fill-last")
})

test("balance ızgarayı dengeli kipe alır", () => {
  const s = renderTest(() => <GridLab />)
  expect(s.get(".lab-balance")?.className).toContain("m-grid-balance")
})
